mapper.update:
update user_invoice_title set is_default = 0
where member_id = #{memberId} and del_flag = 0 and is_default = 1
and id != #{exceptId}

mapper.sql:
where r.member_id = #{memberId} and r.payment_status = 2 and r.registration_status = 2 and r.wechat_payment_amount > 0
and r.id in #{oid}
and not exists ( select 1 from refund_application ra where ra.source_type = 'registration' and ra.source_id = r.id and ra.del_flag = 0 and ra.status in (0, 1)) and not exists ( select 1 from user_invoice_application_order o where o.order_source = 'registration' and o.order_id = r.id and o.active_key = 1)
